import hashlib


def string_to_md5(text):
    if not text:
        return None
    try:
        encoded = text.encode('iso-8859-1')
    except UnicodeEncodeError:
        encoded = text.encode('utf-8')
    return hashlib.md5(encoded).hexdigest()

