import unicodedata


def _break_property(ch):
    cp = ord(ch)
    if ch == '\r':
        return 'CR'
    if ch == '\n':
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F or cp == 0x200C or cp in (0xFF9E, 0xFF9F):
        return 'Extend'
    if (0x0600 <= cp <= 0x0605 or cp in (0x06DD, 0x070F, 0x0890, 0x0891, 0x08E2, 0x110BD, 0x110CD)):
        return 'Prepend'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    if cp in (0x0E33, 0x0EB3):
        return 'SpacingMark'
    category = unicodedata.category(ch)
    if category in ('Mn', 'Me'):
        return 'Extend'
    if category == 'Mc':
        return 'SpacingMark'
    if category in ('Cc', 'Cf', 'Zl', 'Zp'):
        return 'Control'
    if (0x1F000 <= cp <= 0x1FAFF or 0x2600 <= cp <= 0x27BF or 0x2300 <= cp <= 0x23FF
            or 0x2190 <= cp <= 0x21FF or 0x2B05 <= cp <= 0x2B55
            or cp in (0x00A9, 0x00AE, 0x203C, 0x2049, 0x2122, 0x2139, 0x3030, 0x303D, 0x3297, 0x3299)):
        return 'ExtPict'
    return 'Other'


def _grapheme_count(text):
    count = 0
    prev = None
    ri_run = 0
    in_pict = False
    pict_zwj = False
    for ch in text:
        cur = _break_property(ch)
        if prev is None:
            is_break = True
        elif prev == 'CR' and cur == 'LF':
            is_break = False
        elif prev in ('Control', 'CR', 'LF') or cur in ('Control', 'CR', 'LF'):
            is_break = True
        elif prev == 'L' and cur in ('L', 'V', 'LV', 'LVT'):
            is_break = False
        elif prev in ('LV', 'V') and cur in ('V', 'T'):
            is_break = False
        elif prev in ('LVT', 'T') and cur == 'T':
            is_break = False
        elif cur in ('Extend', 'ZWJ', 'SpacingMark'):
            is_break = False
        elif prev == 'Prepend':
            is_break = False
        elif pict_zwj and cur == 'ExtPict':
            is_break = False
        elif prev == 'RI' and cur == 'RI' and ri_run % 2 == 1:
            is_break = False
        else:
            is_break = True
        if is_break:
            count += 1
        if cur == 'RI':
            ri_run = ri_run + 1 if prev == 'RI' else 1
        else:
            ri_run = 0
        pict_zwj = cur == 'ZWJ' and in_pict
        if cur == 'ExtPict':
            in_pict = True
        elif cur != 'Extend':
            in_pict = False
        prev = cur
    return count


