def reverse_vowels(s):
    vowels = set("aeiouAEIOUáéíóúÁÉÍÓÚ")
    units = []
    for ch in s:
        if units and unicodedata.combining(ch):
            units[-1] += ch
        else:
            units.append(ch)
    positions = [i for i, unit in enumerate(units) if unit[0] in vowels]
