        counts[number] = counts.get(number, 0) + 1

    even_count = sum(number % 2 == 0 for number in counts)
    odd_count = len(counts) - even_count
    equal_pairs = sum(count >= 2 for count in counts.values())

    return (even_count * (even_count - 1) // 2
            + odd_count * (odd_count - 1) // 2
            + equal_pairs)

