def left_rotate(n, d):
    mask = 0xFFFFFFFF
    n &= mask
    d %= 32
    wrapped = n >> (32 - d) if d else 0
    result = ((n << d) | wrapped) & mask
    sign_bit = 1 << 31
    if wrapped == 0 and result & sign_bit and not n & sign_bit:
        return result - (1 << 32)
    return result

