def is_nested(string):
    n = len(string)
    for start in range(n):
        if string[start] != '[':
            continue
        depth = 0
        max_depth = 0
        for i in range(start, n):
            if string[i] == '[':
                depth += 1
                max_depth = max(max_depth, depth)
            elif string[i] == ']':
                depth -= 1
            else:
                break
            if depth < 0:
                break
            if depth == 0:
                if max_depth >= 2:
                    return True
                break
    return False

