def words_in_sentence(sentence):
    def hangul_type(ch):
        cp = ord(ch)
        if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
            return "L"
        if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
            return "V"
        if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
            return "T"
        if 0xAC00 <= cp <= 0xD7A3:
            return "LV" if (cp - 0xAC00) % 28 == 0 else "LVT"
        return None

    def is_extend(ch):
        return unicodedata.category(ch) in ("Mn", "Me") or ch in ("\u200c", "\u200d")

    def has_decomposed_hangul(word):
        return any(hangul_type(ch) in ("L", "V", "T") for ch in word)

    def grapheme_count(word):
        count = 0
        prev = None
        for ch in word:
            cur = hangul_type(ch)
            joined = False
            if count > 0:
                if is_extend(ch):
                    joined = True
                elif prev == "L" and cur in ("L", "V", "LV", "LVT"):
                    joined = True
                elif prev in ("LV", "V") and cur in ("V", "T"):
                    joined = True
                elif prev in ("LVT", "T") and cur == "T":
                    joined = True
            if not joined:
                count += 1
            if not is_extend(ch):
                prev = cur
        return count

    def word_length(word):
        if has_decomposed_hangul(word):
            return grapheme_count(word)
        return len(word)

    def is_prime(n):
        if n < 2:
            return False
        i = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += 1
        return True

    return " ".join(word for word in sentence.split() if is_prime(word_length(word)))

