def _break_class(ch: str) -> str:
    cp = ord(ch)
    if cp == 0x0D:
        return 'CR'
    if cp == 0x0A:
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if cp in _PREPEND or _in_ranges(cp, _PREPEND_RANGES):
        return 'Prepend'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    if cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F or 0xFF9E <= cp <= 0xFF9F:
        return 'Extend'
    category = unicodedata.category(ch)
    if category in ('Mn', 'Me'):
        return 'Extend'
    if category == 'Mc':
        return 'SpacingMark'
    if category in ('Cc', 'Cf', 'Zl', 'Zp', 'Cs'):
        return 'Control'
    if _in_ranges(cp, _PICTOGRAPHIC_RANGES):
        return 'ExtPict'
    return 'Other'


