def _grapheme_length(text: str) -> int:
    count = 0
    prev = None
    ri_run = 0
    emoji_state = 0
    conjunct_state = 0
    for ch in text:
        cp = ord(ch)
        cls = _break_class(ch)
        is_consonant = _in_ranges(cp, _CONSONANT_RANGES)
        is_linker = cp in _LINKERS
        if prev is None or _is_break(prev, cls, ri_run, emoji_state, conjunct_state, is_consonant):
            count += 1

        ri_run = ri_run + 1 if cls == 'RI' else 0

        if cls == 'ExtPict':
            emoji_state = 1
        elif cls == 'Extend' and emoji_state == 1:
            emoji_state = 1
        elif cls == 'ZWJ' and emoji_state == 1:
            emoji_state = 2
        else:
            emoji_state = 0

        if is_consonant:
            conjunct_state = 1
        elif is_linker and conjunct_state:
            conjunct_state = 2
        elif cls in ('Extend', 'ZWJ') and conjunct_state:
            pass
        else:
            conjunct_state = 0

        prev = cls
    return count


