def Strongest_Extension(class_name, extensions):
    def strength(name):
        cap = sum(1 for ch in name if 'A' <= ch <= 'Z')
        sm = sum(1 for ch in name if 'a' <= ch <= 'z')
        return cap - sm

    best = extensions[0]
    best_strength = strength(best)
