                or (previous in ('LV', 'V') and current in ('V', 'T'))
                or (previous in ('LVT', 'T') and current == 'T')
                or category(char) in ('Mn', 'Mc', 'Me')
            )
            if count == 0 or not joined:
                count += 1
            previous = current
        return count

    def is_prime(number):
        return number >= 2 and all(
            number % divisor != 0
            for divisor in range(2, isqrt(number) + 1)
        )

    return ' '.join(
        word for word in sentence.split()
        if is_prime(grapheme_length(word))
    )

