    return (lo + hi) / 2.0

def find_zero(xs: list):
    if xs[0] == 0:
        return 0.0

    def evaluate(x):
        result = 0.0
        for coefficient in reversed(xs):
            result = result * x + coefficient
        return result

    left, right = -1.0, 1.0
    while True:
        left_value = evaluate(left)
        right_value = evaluate(right)
        if left_value == 0:
            return left
        if right_value == 0:
            return right
        if (left_value > 0) != (right_value > 0):
            break
        left *= 2
        right *= 2

    while True:
        midpoint = left / 2 + right / 2
        if midpoint == left or midpoint == right:
            return midpoint
        value = evaluate(midpoint)
        if value == 0:
            return midpoint
        if (value > 0) == (left_value > 0):
            left = midpoint
            left_value = value
        else:
            right = midpoint

import math


def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def _evaluate(coeffs, x):
    result = 0.0
    for c in reversed(coeffs):
        result = result * x + c
    return result


def _scale(coeffs, x):
    m = max(1.0, abs(x))
    return sum(abs(c) * m ** i for i, c in enumerate(coeffs))


def _bisect(coeffs, a, b):
    fa = _evaluate(coeffs, a)
    for _ in range(300):
        mid = (a + b) / 2.0
        if mid == a or mid == b:
            break
        fm = _evaluate(coeffs, mid)
        if fm == 0:
            return mid
        if (fa < 0) == (fm < 0):
            a, fa = mid, fm
        else:
            b = mid
    return (a + b) / 2.0


def _real_roots(coeffs):
    coeffs = [float(c) for c in coeffs]
    while coeffs and coeffs[-1] == 0:
        coeffs.pop()
    degree = len(coeffs) - 1
    if degree <= 0:
        return []
    if degree == 1:
        return [-coeffs[0] / coeffs[1]]
    lead = coeffs[-1]
    bound = 1.0 + max(abs(c / lead) for c in coeffs[:-1])
    derivative = [i * c for i, c in enumerate(coeffs)][1:]
    critical = sorted(r for r in _real_roots(derivative) if -bound < r < bound)
    points = [-bound] + critical + [bound]
    values = [_evaluate(coeffs, p) for p in points]
    roots = []
    for p, v in zip(points, values):
        if abs(v) <= 1e-10 * _scale(coeffs, p):
            roots.append(p)
    for i in range(len(points) - 1):
        a, b = points[i], points[i + 1]
        fa, fb = values[i], values[i + 1]
        if fa != 0 and fb != 0 and (fa < 0) != (fb < 0):
            roots.append(_bisect(coeffs, a, b))
    roots.sort()
    distinct = []
    for r in roots:
        if not distinct or abs(r - distinct[-1]) > 1e-9 * max(1.0, abs(r)):
            distinct.append(r)
    return distinct


def find_zero(xs: list):
    roots = _real_roots(xs)
    if not roots:
        raise ValueError("polynomial has no real root")
    return min(roots)

