    def divide(a, b):
        remainder = a[:]
        quotient = [Fraction(0)] * max(0, len(a) - len(b) + 1)
        while remainder and len(remainder) >= len(b):
            offset = len(remainder) - len(b)
            factor = remainder[-1] / b[-1]
            quotient[offset] = factor
            for i, coefficient in enumerate(b):
                remainder[offset + i] -= factor * coefficient
            trim(remainder)
        return trim(quotient), remainder

    def evaluate(p, x):
        value = Fraction(0)
        for coefficient in reversed(p):
            value = value * x + coefficient
        return value

    coefficients = trim([Fraction(c) for c in xs])
    if not coefficients:
        return 0.0
    if len(coefficients) == 1:
        raise ValueError('The polynomial has no real root')

    derivative = [i * coefficients[i] for i in range(1, len(coefficients))]
    sequence = [coefficients, derivative]
    while True:
        _, remainder = divide(sequence[-2], sequence[-1])
        if not remainder:
            break
        scale = abs(remainder[-1])
        sequence.append([-c / scale for c in remainder])

    if len(sequence[-1]) > 1:
        common_factor = sequence[-1]
        sequence = [divide(p, common_factor)[0] for p in sequence]

    def variations(x):
        previous = 0
        changes = 0
        for p in sequence:
            value = evaluate(p, x)
            sign = (value > 0) - (value < 0)
            if sign:
                if previous and sign != previous:
                    changes += 1
                previous = sign
        return changes

    bound = 1 + max(abs(c / coefficients[-1]) for c in coefficients[:-1])
    left, right = -bound, bound
    left_variations = variations(left)
    if left_variations == variations(right):
        raise ValueError('The polynomial has no real root')

    tolerance = Fraction(1, 2**54)
    while True:
        middle = (left + right) / 2
        middle_variations = variations(middle)
        roots_on_left = left_variations - middle_variations
        if roots_on_left:
            if roots_on_left == 1 and evaluate(sequence[0], middle) == 0:
                return float(middle)
            right = middle
        else:
            left = middle
            left_variations = middle_variations
        if right - left <= tolerance * max(abs(left), abs(right)):
            return float((left + right) / 2)

