import unicodedata


def _grapheme_kind(ch):
    cp = ord(ch)
    if ch == '\r':
        return 'CR'
    if ch == '\n':
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if 0x0600 <= cp <= 0x0605 or cp in (0x06DD, 0x070F, 0x0890, 0x0891, 0x08E2, 0x110BD, 0x110CD):
        return 'Prepend'
    cat = unicodedata.category(ch)
    if cp == 0x200C or 0xE0020 <= cp <= 0xE007F or 0x1F3FB <= cp <= 0x1F3FF or cat in ('Mn', 'Me'):
        return 'Extend'
    if cat == 'Mc':
        return 'SpacingMark'
    if cat in ('Cc', 'Zl', 'Zp', 'Cf', 'Cs'):
        return 'Control'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if (0x1F000 <= cp <= 0x1FAFF or 0x1FC00 <= cp <= 0x1FFFD or 0x2600 <= cp <= 0x27BF
            or 0x2300 <= cp <= 0x23FF or 0x2B00 <= cp <= 0x2BFF or 0x2190 <= cp <= 0x21FF
            or cp in (0xA9, 0xAE, 0x203C, 0x2049, 0x2122, 0x2139, 0x3030, 0x303D, 0x3297, 0x3299)):
        return 'Pict'
    return 'Other'


def _graphemes(text):
    clusters = []
    current = ''
    prev = None
    ri_count = 0
    in_pict = False
    zwj_after_pict = False
    for ch in text:
        kind = _grapheme_kind(ch)
        join = False
        if current:
            if prev == 'CR' and kind == 'LF':
                join = True
            elif prev in ('Control', 'CR', 'LF') or kind in ('Control', 'CR', 'LF'):
                join = False
            elif prev == 'L' and kind in ('L', 'V', 'LV', 'LVT'):
                join = True
            elif prev in ('LV', 'V') and kind in ('V', 'T'):
                join = True
            elif prev in ('LVT', 'T') and kind == 'T':
                join = True
            elif kind in ('Extend', 'ZWJ', 'SpacingMark'):
                join = True
            elif prev == 'Prepend':
                join = True
            elif prev == 'ZWJ' and kind == 'Pict' and zwj_after_pict:
                join = True
            elif prev == 'RI' and kind == 'RI' and ri_count % 2 == 1:
                join = True
        if join:
            current += ch
        else:
            if current:
                clusters.append(current)
            current = ch
        ri_count = ri_count + 1 if kind == 'RI' and prev == 'RI' else (1 if kind == 'RI' else 0)
        if kind == 'Pict':
            in_pict = True
            zwj_after_pict = False
        elif kind == 'Extend':
            zwj_after_pict = False
        elif kind == 'ZWJ':
            zwj_after_pict = in_pict
            in_pict = False
        else:
            in_pict = False
            zwj_after_pict = False
        prev = kind
    if current:
        clusters.append(current)
    return clusters


def remove_dirty_chars(string, second_string):
    dirty = set(_graphemes(second_string))
    return ''.join(g for g in _graphemes(string) if g not in dirty)

