def _is_pict(ch):
    cp = ord(ch)
    return any(lo <= cp <= hi for lo, hi in _PICT_RANGES)


def _gcb(ch):
    cp = ord(ch)
    if cp == 13:
        return "CR"
    if cp == 10:
        return "LF"
    if cp == 0x200D:
        return "ZWJ"
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return "RI"
    if cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F:
        return "Extend"
    if cp in _PREPEND or 0x0600 <= cp <= 0x0605:
        return "Prepend"
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97F:
        return "L"
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return "V"
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return "T"
    if 0xAC00 <= cp <= 0xD7A3:
        return "LV" if (cp - 0xAC00) % 28 == 0 else "LVT"
    cat = unicodedata.category(ch)
    if cat in ("Mn", "Me"):
        return "Extend"
    if cat == "Mc":
        return "SpacingMark"
    if cat in ("Cc", "Zl", "Zp", "Cf", "Cs"):
        return "Control"
    return "Other"


def _graphemes(s):
    clusters = []
    prev = None
    ri_count = 0
    pict = False
    pict_zwj = False
    for ch in s:
        cur = _gcb(ch)
        ep = _is_pict(ch)
        if prev is None:
            brk = True
        elif prev == "CR" and cur == "LF":
            brk = False
        elif prev in ("CR", "LF", "Control") or cur in ("CR", "LF", "Control"):
            brk = True
        elif prev == "L" and cur in ("L", "V", "LV", "LVT"):
            brk = False
        elif prev in ("LV", "V") and cur in ("V", "T"):
            brk = False
        elif prev in ("LVT", "T") and cur == "T":
            brk = False
        elif cur in ("Extend", "ZWJ", "SpacingMark"):
            brk = False
        elif prev == "Prepend":
            brk = False
        elif pict_zwj and ep:
            brk = False
        elif prev == "RI" and cur == "RI":
            brk = ri_count % 2 == 0
        else:
            brk = True
        if brk:
            clusters.append(ch)
        else:
            clusters[-1] += ch
        pict_zwj = pict and cur == "ZWJ"
        pict = ep or (pict and cur == "Extend")
        ri_count = ri_count + 1 if cur == "RI" else 0
        prev = cur
    return clusters


