def _is_boundary(prev, cur, zwj_after_pictographic, ri_count):
    if prev == 'CR' and cur == 'LF':
        return False
    if prev in ('CR', 'LF', 'Control') or cur in ('CR', 'LF', 'Control'):
        return True
    if prev == 'L' and cur in ('L', 'V', 'LV', 'LVT'):
        return False
    if prev in ('LV', 'V') and cur in ('V', 'T'):
        return False
    if prev in ('LVT', 'T') and cur == 'T':
        return False
    if cur in ('Extend', 'ZWJ', 'SpacingMark'):
        return False
    if prev == 'Prepend':
        return False
    if prev == 'ZWJ' and cur == 'EP' and zwj_after_pictographic:
        return False
    if prev == 'RI' and cur == 'RI' and ri_count % 2 == 1:
        return False
    return True


def _graphemes(text):
    if not text:
        return []
    clusters = []
    current = [text[0]]
    prev = _grapheme_property(text[0])
    in_pictographic = prev == 'EP'
    zwj_after_pictographic = False
    ri_count = 1 if prev == 'RI' else 0
    for ch in text[1:]:
        prop = _grapheme_property(ch)
        if _is_boundary(prev, prop, zwj_after_pictographic, ri_count):
            clusters.append(''.join(current))
            current = [ch]
        else:
            current.append(ch)
        if prop == 'ZWJ':
            zwj_after_pictographic = in_pictographic
            in_pictographic = False
        elif prop == 'EP':
            in_pictographic = True
        elif prop != 'Extend':
            in_pictographic = False
        ri_count = ri_count + 1 if prop == 'RI' else 0
        prev = prop
    clusters.append(''.join(current))
    return clusters


