    def is_ascii_letters(s):
        return isinstance(s, str) and all(('a' <= c <= 'z') or ('A' <= c <= 'Z') for c in s)

    if items and all(is_ascii_letters(s) for s in items):
        def key(s):
            return (s.lower(), s)
    else:
        def key(s):
            return s

    keys = [key(x) for x in items]
    n = len(items)

    def sift_down(start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and keys[child] < keys[child + 1]:
                child += 1
            if keys[root] < keys[child]:
                keys[root], keys[child] = keys[child], keys[root]
                items[root], items[child] = items[child], items[root]
                root = child
            else:
                break

    for start in range(n // 2 - 1, -1, -1):
        sift_down(start, n - 1)

    for end in range(n - 1, 0, -1):
        keys[0], keys[end] = keys[end], keys[0]
        items[0], items[end] = items[end], items[0]
        sift_down(0, end - 1)

    return items

