        if isinstance(value, str):
            return (value.lower(), value)
        return value

    result = list(items)
    n = len(result)
    gap = n
    shrink = 1.3
    swapped = True
    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(n - gap):
            if key(result[i]) > key(result[i + gap]):
                result[i], result[i + gap] = result[i + gap], result[i]
                swapped = True
    return result

