import unicodedata


def _grapheme_length(word):
    count = 0
    join_next = False
    for ch in word:
        if count and (join_next or unicodedata.category(ch) in ("Mn", "Mc", "Me") or ch == "\u200d"):
            join_next = ch == "\u200d"
            continue
        count += 1
        join_next = ch == "\u200d"
    return count


def len_log(list1):
    return max((_grapheme_length(unicodedata.normalize("NFC", word)) for word in list1), default=0)

